import socket

COMMAND_CENTER_IP = "100.99.95.118"
COMMAND_CENTER_PORT = 9999

cc_cmd_queue = queue.Queue()
cc_socket = None

def cc_client_thread():
    global cc_socket
    while True:
        try:
            cc_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            cc_socket.settimeout(5.0)
            cc_socket.connect((COMMAND_CENTER_IP, COMMAND_CENTER_PORT))
            cc_socket.settimeout(None)
            print(f"📡 [네트워크] 통제실({COMMAND_CENTER_IP}:{COMMAND_CENTER_PORT}) 접속 완료!")

            while True:
                data = cc_socket.recv(4096)
                if not data: break

                msgs = data.decode('utf-8').strip().split('\n')
                for m in msgs:
                    if m:
                        try:
                            cmd = json.loads(m)
                            cc_cmd_queue.put(cmd)
                        except json.JSONDecodeError: pass

        except Exception:
            if cc_socket:
                try: cc_socket.close()
                except: pass
            cc_socket = None
        time.sleep(3.0)

threading.Thread(target=cc_client_thread, daemon=True).start()

def send_to_cc(action, **kwargs):
    global cc_socket
    if not cc_socket: return False
    try:
        payload = {"action": action}
        payload.update(kwargs)
        cc_socket.send((json.dumps(payload, ensure_ascii=False) + "\n").encode('utf-8'))
        return True
    except:
        return False

import socket
import threading
import json
import time

LOCAL_IPC_PORTS = {
    "미니1": 50001, "미니2": 50002, "미니3": 50003, "미니4": 50004
}

local_party_states = {}
party_lock = threading.Lock()

def local_ipc_listener_thread(my_key):
    """내 전용 포트를 열고 파티원들의 외침을 듣는 귀(Receiver)"""
    my_port = LOCAL_IPC_PORTS.get(my_key)
    if not my_port: return

    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.bind(('127.0.0.1', my_port))
    sock.setblocking(False)
    print(f"📡 [파티 로컬망] {my_key} 전용 수신 포트({my_port}) 개통 완료!")

    while True:
        try:
            while True:
                data, _ = sock.recvfrom(4096)
                msg = json.loads(data.decode('utf-8'))

                sender_key = msg.get("pc_key")
                sender_party = msg.get("party_group")
                my_party = current_settings.get(my_key, {}).get("party_group", "선택안함")

                if sender_key != my_key and my_party != "선택안함" and sender_party == my_party:
                    with party_lock:
                        msg["recv_time"] = time.time()
                        local_party_states[sender_key] = msg
        except BlockingIOError: pass
        except Exception: pass
        time.sleep(0.05)

def local_ipc_broadcaster_thread(my_key):
    """내 상태와 '내가 치고 있는 몹의 절대 좌표(GPS)'를 파티원에게 0.1초마다 쏴주는 입(Sender)"""
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)

    while True:
        try:
            my_party = current_settings.get(my_key, {}).get("party_group", "선택안함")
            use_party_hunt = current_settings.get(my_key, {}).get("use_party_hunt", False)
            use_party_fixed = current_settings.get(my_key, {}).get("use_party_fixed", False)
            st = ai_states.get(my_key, {})

            if (use_party_hunt or use_party_fixed) and my_party != "선택안함":
                hp = st.get("last_hp", 100.0)
                mp = sorted(st.get("mp_buffer", [100.0]*5))[2] if "mp_buffer" in st else 100.0
                my_map_pos = st.get("dungeon_map_pos")

                raw_fsm = str(st.get("target_fsm", "IDLE"))
                party_state = "IDLE"

                if "DEATH" in raw_fsm or "TOWN_MAINT" in raw_fsm or "SHUTDOWN" in raw_fsm:
                    if "MP_REST" in raw_fsm or "MOTHER" in raw_fsm: party_state = "MPTAM"
                    else: party_state = "TOWN"
                elif st.get("is_mptam_mode", False): party_state = "MPTAM"
                elif "INV_CLEAN" in raw_fsm or "WEAPON_REPAIR" in raw_fsm or "HK_HEAL" in raw_fsm: party_state = "MAINT"

                elif "EMERGENCY" in raw_fsm or st.get("perc_pk", 0) > 0: party_state = "SURVIVAL"
                elif "MOTION_EVADING" in raw_fsm or raw_fsm.startswith("PARTY_"): party_state = "TACTIC"

                elif st.get("is_mptam_mode", False) or st.get("mptam_extend_95", False) or st.get("moving_to_mptam_partner", False): party_state = "MPTAM"
                elif raw_fsm.startswith("PARTY_"): party_state = "TACTIC"
                elif st.get("is_attacking", False) or st.get("arrow_is_firing", False) or raw_fsm in ["COMBAT", "HOVER_WAIT", "SNAP_WAIT", "MOTION_SNAP_CHECK_SWORD", "TARGET_AIMING", "HEINE_GMOB_VERIFY"]: party_state = "COMBAT"
                elif raw_fsm.startswith("LOOT") or st.get("sweep_active", False): party_state = "LOOTING"
                else: party_state = "IDLE"

                mob_map_pos = None
                if party_state == "COMBAT" and my_map_pos:
                    mob_screen_pos = None
                    is_motion = st.get("is_motion_target", False)

                    if not is_motion and st.get("last_mob_pos"):

                        mob_screen_pos = st.get("last_mob_pos")
                    elif is_motion and st.get("hover_pos"):

                        mob_screen_pos = st.get("hover_pos")
                    elif st.get("cursor_pos"):
                        mob_screen_pos = st.get("cursor_pos")

                    if mob_screen_pos:
                        try:

                            scale_x = globals().get("DUNGEON_SCALE_X", 0.1)
                            scale_y = globals().get("DUNGEON_SCALE_Y", 0.1)

                            if not is_motion:

                                mob_map_x = my_map_pos[0] + (mob_screen_pos[0] - 400) * scale_x
                                mob_map_y = my_map_pos[1] + (mob_screen_pos[1] + 10 - 245) * scale_y
                                mob_map_pos = (mob_map_x, mob_map_y)
                            else:

                                dx = mob_screen_pos[0] - 400
                                dy = (mob_screen_pos[1] - 245) / 0.85
                                if math.hypot(dx, dy) > 10:
                                    angle = math.atan2(dy, dx)
                                    snap_angle = round(angle / (math.pi / 4)) * (math.pi / 4)
                                    mob_map_x = my_map_pos[0] + math.cos(snap_angle) * 5.0
                                    mob_map_y = my_map_pos[1] + math.sin(snap_angle) * 5.0
                                    mob_map_pos = (mob_map_x, mob_map_y)
                        except: pass

                payload = {
                    "pc_key": my_key,
                    "party_group": my_party,
                    "is_party_inviter": current_settings.get(my_key, {}).get("is_party_inviter", False),
                    "party_state": party_state,
                    "mob_map_pos": mob_map_pos,
                    "hp": hp,
                    "mp": mp,
                    "map_pos": my_map_pos,
                    "target_node": st.get("current_target_node"),
                    "hidden_node": st.get("hidden_track_node"),
                    "is_mptam": st.get("is_mptam_mode", False),
                    "req_heal": st.get("mptam_req_heal", False),
                    "ack_heal": st.get("mptam_ack_heal", ""),
                    "heal_received": st.get("mptam_heal_received", False),
                    "is_help_req": st.get("help_requester", False),
                    "help_req_pos": st.get("dungeon_map_pos") if st.get("help_requester", False) else None,

                    "is_helping": st.get("helping_who") is not None,
                    "helping_who": st.get("helping_who", None),
                    "claimed_base_node": st.get("claimed_base_node", None),
                    "designated_base_node": st.get("designated_base_node", None),

                    "req_party_buff": st.get("req_party_buff", False),
                    "party_buff_status": st.get("party_buff_status", "IDLE"),
                    "party_buff_done": st.get("party_buff_done", False),
                    "dungeon_name": current_settings.get(my_key, {}).get("dungeon_name", ""),
                    "is_out_of_zone": st.get("is_out_of_zone", False)
                }

                data = json.dumps(payload).encode('utf-8')
                for k, port in LOCAL_IPC_PORTS.items():
                    if k != my_key:
                        try: sock.sendto(data, ('127.0.0.1', port))
                        except: pass

        except Exception: pass
        time.sleep(0.1)

