                                                    try: ANT_IN_X1_v = globals().get("ANT_IN_X1", 1)
                                                    except: ANT_IN_X1_v = 1
                                                    try: ANT_IN_X2_v = globals().get("ANT_IN_X2", 130)
                                                    except: ANT_IN_X2_v = 130
                                                    try: ANT_IN_Y1_v = globals().get("ANT_IN_Y1", 437)
                                                    except: ANT_IN_Y1_v = 437
