                                                            sudun_in_tmpl = loaded_models.get("sudun_in_img")
                                                            if sudun_in_tmpl and sudun_in_tmpl["color"] is not None:
                                                                roi_gray = cv2.cvtColor(ui_check_roi, cv2.COLOR_BGR2GRAY)
