                                #     pico_queues[key].put({"action": "WAIT", "delay_min": 0.2, "delay_max": 0.3})
                                #     pico_queues[key].put({"action": "HOLD_KEY", "keycode": 202, "duration": g_val(0.08, 0.15)})
                                # 
